// src/original/bridge/server.ts
function bridgeAvailable() {
  try {
    return !!nativeHost();
  } catch {
    return false;
  }
}

// src/original/bridge/session.ts
async function startBridgeRun(options2) {
  const api2 = nativeHost();
  const assets = [];
  for (const asset of options2.job.assets) {
    const value2 = await options2.readAsset(asset.id);
    if (!value2) throw Error(`Missing publishing asset: ${asset.name}`);
    assets.push({ id: asset.id, mime: value2.mime, base64: bytesToBase64(new Uint8Array(value2.data)) });
  }
  const started = await api2.bridgeStart({ job: options2.job, assets });
  let finished = false, timer4;
  let settle;
  const done = new Promise((resolve2) => {
    settle = resolve2;
  });
  const finish = (status) => {
    if (finished) return;
    finished = true;
    clearTimeout(timer4);
    settle(status);
  };
  const poll = async () => {
    try {
      const result = await api2.bridgeStatus({ id: started.id });
      options2.onStatus(result.status);
      if (result.finished) finish(result.status);
      else timer4 = setTimeout(poll, 500);
    } catch {
      void api2.bridgeCancel({ id: started.id }).catch(() => {
      });
      finish({ state: "error", error: { message: "Local publishing service disconnected" } });
    }
  };
  try {
    options2.open(started.url);
  } catch (error3) {
    await api2.bridgeCancel({ id: started.id });
    throw error3;
  }
  void poll();
  return { done, url: started.url, cancel: () => {
    void api2.bridgeCancel({ id: started.id }).catch(() => finish({ state: "cancelled" }));
  } };
}

